INSERT INTO FeatureType (Name, Description) VALUES 
('AtrRatio', 'Measures the current bar''s trading range compared with the market''s typical recent volatility (ATR). Higher values mean the bar is unusually large relative to normal movement.')
,('AtrVsOpen', 'Measures the current price''s movement relative to the Average True Range (ATR), using the day''s opening price as the reference. It indicates how far the market has moved compared with its typical volatility.')
,('AvgRange', 'The average size of recent price bars, measured from each bar''s high to low. It represents the market''s typical short-term price movement.')
,('BodySize', 'The size of the candle''s body—the distance between its opening and closing prices. It indicates how much price actually moved during the bar, ignoring the wicks.')
,('ClosePosition', 'Indicates where the closing price falls within the bar''s high-to-low range. A value near 1 means the bar closed near its high; a value near 0 means it closed near its low.')
,('DayOfMonth', 'The calendar day of the month on which the bar occurred, from 1 through 31.')
,('DayOfWeek', 'The day of the week on which the bar occurred, typically represented as a number or category such as Monday through Friday.')
,('FirstHalfHourRange', 'The price range between the highest and lowest prices during the first 30 minutes of the regular trading session.')
,('FirstHourRange', 'The price range between the highest and lowest prices during the first hour of the regular trading session.')
,('GapToRthOpen', 'The difference between the current price and the regular trading hours (RTH) opening price. It indicates how far price has moved from the RTH open.')
,('HighLowRange', 'The difference between the bar''s high and low prices. It represents the total price movement within the bar.')
,('HighTimeRatio', 'Indicates how far through the trading session the day''s high occurred. A lower value means the high occurred earlier; a higher value means it occurred later.')
,('LastHourClosePosition', 'Indicates where the most recent close falls within the high-to-low range established during the last hour.')
,('LastHourRange', 'The price range between the highest and lowest prices during the most recent hour of trading.')
,('LowTimeRatio', 'Indicates how far through the trading session the day''s low occurred. A lower value means the low occurred earlier; a higher value means it occurred later.')
,('LowerWick', 'The distance between the bar''s low and the lower edge of its body (open or close). It represents the amount of downward price movement that was rejected before the bar closed.')
,('OpenToHighRatio', 'Measures the distance from the bar''s opening price to its high relative to the bar''s overall range. It indicates how much of the bar''s movement was upward from the open.')
,('OpenToLowRatio', 'Measures the distance from the bar''s opening price to its low relative to the bar''s overall range. It indicates how much of the bar''s movement was downward from the open.')
,('OpenVsPrevClose', 'Measures the difference between the current bar''s opening price and the previous bar''s closing price. It indicates whether the market opened higher or lower than the previous close.')
,('OpenVsPrevHigh', 'Measures the current bar''s opening price relative to the previous bar''s high. It indicates whether the market opened above, below, or near the previous bar''s high.')
,('OpenVsPrevLow', 'Measures the current bar''s opening price relative to the previous bar''s low. It indicates whether the market opened above, below, or near the previous bar''s low.')
,('OpenVsSma', 'Measures the current price or bar''s opening price relative to its Simple Moving Average (SMA). It indicates whether price is above or below its recent average.')
,('OvernightDropRatio', 'Measures the size of the overnight price decline relative to the overnight trading range. It indicates how significant the downward move was during the overnight session.')
,('OvernightRange', 'The difference between the highest and lowest prices during the overnight trading session. It represents the total price movement before the regular trading session begins.')
,('OvernightVolumeRatio', 'Compares overnight trading volume with a typical or reference volume level. It indicates whether overnight trading activity was unusually high or low.')
,('PreMarketHighVsOpen', 'Measures the pre-market high relative to the regular trading hours (RTH) opening price. It indicates how far the pre-market high was above or below the RTH open.')
,('PreMarketLowVsOpen', 'Measures the pre-market low relative to the regular trading hours (RTH) opening price. It indicates how far the pre-market low was above or below the RTH open.')
,('PreMarketRange', 'The difference between the highest and lowest prices during the pre-market period. It represents the total price movement before the regular trading session begins.')
,('PreMarketVolumeRatio', 'Compares pre-market trading volume with a typical or reference volume level. It indicates whether pre-market trading activity was unusually high or low.')
,('PrevHighVsOpen', 'Measures the previous bar''s high relative to the current bar''s opening price. It indicates how the current open compares with the previous bar''s highest price.')
,('PrevLowVsOpen', 'Measures the previous bar''s low relative to the current bar''s opening price. It indicates how the current open compares with the previous bar''s lowest price.')
,('RangeVsAvgRange10', 'Compares the current bar''s high-to-low range with the average range of recent bars. It indicates whether the current bar is larger or smaller than normal.')
,('RegularHoursRange', 'The difference between the highest and lowest prices during the regular trading session (RTH). It represents the total price movement during regular market hours.')
,('Return', 'Measures the percentage change in price from a previous point to the current price. It indicates how much the market has gained or lost over the specified period.')
,('Rsi', 'The Relative Strength Index (RSI), which measures the strength of recent upward price movements compared with downward movements. It is commonly used to identify relatively strong upward or downward momentum.')
,('RthHighTimeRatio', 'Indicates how far through the regular trading session (RTH) the day''s highest price occurred. A lower value means the high occurred earlier; a higher value means it occurred later.')
,('RthLowTimeRatio', 'Indicates how far through the regular trading session (RTH) the day''s lowest price occurred. A lower value means the low occurred earlier; a higher value means it occurred later.')
,('RthOpenToHighRatio', 'Measures the distance from the RTH opening price to the day''s high relative to the RTH trading range. It indicates how much of the day''s upward movement occurred above the RTH open.')
,('RthOpenToLowRatio', 'Measures the distance from the RTH opening price to the day''s low relative to the RTH trading range. It indicates how much of the day''s downward movement occurred below the RTH open.')
,('RthRange', 'The difference between the highest and lowest prices reached during the regular trading session (RTH). It represents the total price movement during the session.')
,('SmaRatio', 'Compares the current price with its Simple Moving Average (SMA). It indicates how far price is above or below its recent average.')
,('UpperWick', 'The distance between the bar''s high and the upper edge of its body (open or close). It represents upward price movement that was rejected before the bar closed.')
,('VolumeSma', 'The Simple Moving Average (SMA) of trading volume over a specified number of previous bars. It represents the typical recent trading volume.')
,('VolumeZScore', 'Measures how unusual the current trading volume is compared with its recent average and variability. A positive value means volume is above normal, while a negative value means it is below normal.')
